theorem two_key_execution :
    run 0 ([0, 1] : List Nat) =
      PMF.map (fun i : Fin 2 =>
        if i = 0 then (some 0, ([(2, 0)], 11))
        else (some 0, ([(2, 1), (1, 0)], 20)))
        (Resources.RandomQuickSort.uniformIndex 1)

private theorem weighted_mono_support (p : PMF α) (f g : α → ℝ≥0∞)
    (h : ∀ a ∈ p.support, f a ≤ g a) :
    (∑' a, p a * f a) ≤ ∑' a, p a * g a

private theorem lintegral_nat_le_of_support (p : PMF Nat) (b : Nat)
    (h : p.support ⊆ Set.Iic b) :
    (∫⁻ k : Nat, (k : ℝ≥0∞) ∂p.toMeasure) ≤ (b : ℝ≥0∞)

private theorem integrable_nat_of_lower_finite (p : PMF Nat)
    (hf : (∫⁻ k : Nat, (k : ℝ≥0∞) ∂p.toMeasure) ≠ ∞) :
    Integrable (fun k : Nat => (k : ℝ)) p.toMeasure

private theorem integral_nat_eq (p : PMF Nat) :
    (∫ k : Nat, (k : ℝ) ∂p.toMeasure) =
      (∫⁻ k : Nat, (k : ℝ≥0∞) ∂p.toMeasure).toReal

private theorem integral_nat_map_fin {n : Nat} (p : PMF (Fin n)) (f : Fin n → Nat) :
    (∫ k : Nat, (k : ℝ) ∂(p.map f).toMeasure) =
      ∑ i : Fin n, (p i).toReal * (f i : ℝ)

private theorem filter_length_eq_card_indices (xs : List α) (p : α → Bool) :
    (xs.filter p).length =
      (Finset.univ.filter (fun i : Fin xs.length => p (xs[i.val]'i.isLt))).card
